CustomCss:
body{font-family:'Georgia','Iowan Old Style',ui-serif,serif;letter-spacing:.15px}
h1,h2,h3,.nlbl{font-family:ui-serif,Georgia,serif}
h2{padding-bottom:8px;border-bottom:1px solid var(--b)}
.form,.sc,.ig,table{border-radius:16px}
.form,.sc{box-shadow:0 1px 4px rgba(87,82,121,.05)}
.ni{border-radius:0 12px 12px 0}
.ni.active{background:rgba(196,167,231,.14);font-weight:600}
button.bp,button.bd,button.bw,button.bsm{border-radius:12px;font-weight:600}
input,select,textarea{border-radius:12px}
input:focus,select:focus,textarea:focus{border-color:var(--a);box-shadow:0 0 0 3px rgba(196,167,231,.2)}
th{font-style:italic;font-weight:600}
.pnl.active{animation:rpIn .3s ease}
@keyframes rpIn{from{opacity:0}to{opacity:1}}
